// ---------- Lease pipeline ----------
const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const gbpK = (n) => (Math.abs(n) >= 1000 ? (n < 0 ? '−' : '') + '£' + (Math.abs(n) / 1000).toFixed(Math.abs(n) % 1000 === 0 ? 0 : 1) + 'k' : gbp(n));
const PILL = 'inline-flex w-fit items-center rounded-full bg-[#F5C22B] px-2 py-0.5 font-mono text-[10px] font-bold text-neutral-950';

function pipelineCard(d) {
  const assessed = d.base != null;
  const margin = assessed ? d.base - d.ask : null;
  const pct = assessed ? Math.round((margin / d.ask) * 100) : null;
  const tile = (label, inner) => `<div class="rounded-xl border border-neutral-200 bg-[#F6F5F2] p-3"><p class="font-mono text-[9px] uppercase tracking-[0.15em] text-neutral-500">${label}</p>${inner}</div>`;
  const live = d.live ? `<span class="mt-3 inline-flex w-fit items-center rounded-full border border-[#F5C22B]/60 bg-[#F5C22B]/25 px-2.5 py-1 font-mono text-[10px] font-bold uppercase tracking-[0.18em] text-neutral-950">${d.live}</span>` : '';
  return `<article id="deal-${d.id}" class="flex h-full scroll-mt-24 flex-col rounded-2xl border border-neutral-200 bg-white p-4 shadow-xs sm:p-6"><div class="flex items-center justify-between gap-3"><span class="inline-flex items-center rounded-full bg-[#F5C22B] px-2.5 py-1 font-mono text-[10px] font-bold uppercase tracking-wider text-neutral-950">${d.id}</span><span class="inline-flex items-center rounded-full border border-neutral-200 bg-neutral-100 px-2.5 py-1 font-mono text-[10px] font-semibold uppercase tracking-wider text-neutral-600">${d.stage}</span></div>${live}<p class="font-mono text-[10px] uppercase tracking-[0.2em] text-neutral-500 ${d.live ? 'mt-3' : 'mt-4'}">${d.cat}</p><h3 class="mt-2 font-serif text-xl font-medium leading-snug tracking-tight text-neutral-950 sm:text-2xl">${d.title}</h3><p class="mt-2.5 text-xs text-neutral-500">${d.area}</p><p class="mt-1 text-xs leading-relaxed text-neutral-400">${d.spec}</p><div class="mt-4 grid grid-cols-1 gap-3 min-[400px]:grid-cols-2">${tile('Owner ask', `<p class="mt-1.5 text-[13px] font-semibold leading-snug text-neutral-900">${d.askText}</p>`)}${tile('Indicative achievable rent', assessed ? `<p class="mt-1.5 text-[13px] font-semibold leading-snug text-neutral-900">${gbp(d.low)}–${gbp(d.high)} / mo</p><p class="mt-1.5"><span class="${PILL}">base ${gbp(d.base)}</span></p>` : `<p class="mt-1.5 text-[13px] font-semibold leading-snug text-neutral-900">Not assessed</p><p class="mt-1.5 font-mono text-[13px] text-neutral-400">—</p>`)}</div><div class="mt-3 grid grid-cols-1 gap-3 min-[400px]:grid-cols-2">${tile('Base monthly margin', assessed ? `<p class="mt-1.5"><span class="${PILL}">${margin < 0 ? '−' : ''}${gbp(Math.abs(margin))}</span></p><p class="mt-1.5 text-[11px] text-neutral-500">${pct}% of ask</p>` : `<p class="mt-1.5 text-[11px] text-neutral-500">—</p><p class="mt-1.5 text-[11px] text-neutral-500">—</p>`)}${tile('Confidence', `<span class="mt-1.5 inline-flex w-fit items-center rounded-full border border-neutral-300 bg-white px-2.5 py-1 font-mono text-[10px] font-semibold uppercase tracking-wider text-neutral-700">${d.conf}</span>`)}</div><p class="mt-3 text-[11px] leading-relaxed text-neutral-400">${d.notes}</p><a href="#comparison" class="mt-auto flex items-center justify-center gap-2 rounded-xl border border-neutral-950 bg-white px-4 pt-4 pb-2.5 font-mono text-[10px] font-bold uppercase tracking-[0.15em] text-neutral-950 transition-colors hover:bg-neutral-950 hover:text-white">Run the numbers${icon('arrow-right', 'h-3.5 w-3.5')}</a></article>`;
}

function pipelineRow(d, i) {
  const assessed = d.base != null;
  const margin = assessed ? d.base - d.ask : 0;
  const pct = assessed ? Math.round((margin / d.ask) * 100) : null;
  const netAnnual = assessed ? margin * 12 - d.costs : null;
  const confRank = { 'High': 3, 'Medium': 2, 'Low–Medium': 1, 'Low': 0 }[d.conf] ?? 0;
  const stageRank = { 'Signed': 5, 'Heads of Terms': 4, 'Validating': 3, 'Screening': 2, 'Passed': 0 }[d.stage] ?? 1;
  const td = 'p-3 align-top sm:p-4';
  return `<tr class="${i % 2 ? 'bg-[#F6F5F2]/60' : 'bg-white'}" data-sort-id="${d.id}" data-sort-title="${attr(d.title)}" data-sort-ask="${d.ask ?? -1}" data-sort-base="${d.base ?? -1}" data-sort-margin="${assessed ? margin : -999999}" data-sort-pct="${pct ?? -999}" data-sort-costs="${d.costs}" data-sort-net="${netAnnual ?? -999999}" data-sort-conf="${confRank}" data-sort-stage="${stageRank}" data-sort-from="${attr(d.from)}"><td class="${td} sticky left-0 z-10 border-r border-neutral-200 bg-inherit shadow-[6px_0_10px_-8px_rgba(10,10,10,0.15)]"><span class="${PILL}">${d.id}</span></td><td class="max-w-[300px] p-4 align-top"><p class="font-semibold leading-snug text-neutral-950">${d.title}</p><p class="mt-1 text-[11px] text-neutral-500">${d.area}</p></td><td class="${td} leading-relaxed text-neutral-700">${d.askText}</td><td class="${td}">${assessed ? `<p class="font-semibold text-neutral-950">${gbp(d.low)}–${gbp(d.high)} / mo</p><p class="mt-1"><span class="${PILL}">base ${gbp(d.base)}</span></p>` : `<p class="font-semibold text-neutral-950">Not assessed</p><p class="mt-1 font-mono text-[11px] text-neutral-400">—</p>`}</td><td class="${td}">${assessed ? `<span class="${PILL}">${margin < 0 ? '−' : ''}${gbp(Math.abs(margin))} / mo</span>` : '<span class="font-mono text-neutral-400">—</span>'}</td><td class="${td} text-neutral-700">${assessed ? pct + '% of ask' : '—'}</td><td class="${td} text-neutral-700">${gbpK(d.costs)}</td><td class="${td}">${assessed ? `<p class="font-semibold text-neutral-950">${netAnnual < 0 ? '−' : ''}${gbpK(Math.abs(netAnnual))}</p><p class="mt-1 font-mono text-[11px] text-neutral-400">${d.tbd} TBD</p>` : `<p class="font-semibold text-neutral-950">Not assessed</p><p class="mt-1 font-mono text-[11px] text-neutral-400">—</p>`}</td><td class="${td} text-neutral-700">${d.conf}</td><td class="${td} text-neutral-700">${d.stage}</td><td class="${td} text-neutral-700">${d.from}</td><td class="${td}"><a href="#deal-${d.id}" class="inline-flex items-center gap-1.5 font-mono text-[10px] font-bold uppercase tracking-wider text-neutral-950 transition-colors hover:underline">Open${icon('external-link', 'h-3 w-3')}</a></td></tr>`;
}

function buildPipeline() {
  const P = C.PIPELINE;
  const bullets = P.bullets.map((b) => `<li class="flex gap-2.5"><span aria-hidden="true" class="mt-[7px] h-1.5 w-1.5 shrink-0 rounded-full bg-[#F5C22B]"></span><span>${b}</span></li>`).join('');
  const cards = P.items.map(pipelineCard).join('');
  const cols = [['id', 'Ref'], ['title', 'Title + location'], ['ask', 'Owner ask'], ['base', 'Indicative achievable rent'], ['margin', 'Base monthly margin'], ['pct', 'Margin %'], ['costs', 'Known set-up costs'], ['net', 'Net annual after known costs'], ['conf', 'Confidence'], ['stage', 'Stage'], ['from', 'Available from'], [null, 'Open →']];
  const ths = cols.map(([key, label], i) => `<th scope="col" aria-sort="none" class="whitespace-nowrap p-3 align-bottom sm:p-4 ${i === 0 ? 'sticky left-0 z-10 border-r border-neutral-200 shadow-[6px_0_10px_-8px_rgba(10,10,10,0.2)] bg-[#F6F5F2]' : ''}">${key ? `<button type="button" data-sort="${key}" class="inline-flex items-center gap-1.5 py-1 uppercase tracking-wider transition-colors text-neutral-600 hover:text-neutral-950">${label}${icon('chevrons-up-down', 'h-3 w-3 opacity-40')}</button>` : `<span class="inline-flex items-center gap-1.5 py-1 uppercase tracking-wider text-neutral-600">${label}</span>`}</th>`).join('');
  const rows = P.items.map(pipelineRow).join('');
  const jsonLd = `\n    <script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@type': 'CollectionPage', name: P.title, description: P.intro, mainEntity: { '@type': 'ItemList', numberOfItems: P.items.length, itemListElement: P.items.map((d, i) => ({ '@type': 'ListItem', position: i + 1, name: d.title, description: `${d.cat} · ${d.area}` })) } })}</script>`;
  const body = `<div class="w-full space-y-12 pt-10 pb-20 sm:space-y-16"><section aria-label="Lease pipeline overview" class="mx-auto w-full max-w-5xl space-y-5 px-4 sm:px-6 sm:space-y-8"><div class="space-y-4 text-center"><div class="inline-flex items-center gap-2 rounded-full border border-neutral-200 bg-white px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.25em] text-neutral-500 shadow-xs">${P.badge}</div><h1 class="font-serif text-4xl font-medium tracking-tight text-neutral-950 sm:text-6xl">${P.title}</h1><p class="mx-auto max-w-2xl text-base leading-relaxed text-neutral-600 sm:text-lg">${P.intro}</p></div><ul class="mx-auto max-w-3xl space-y-2.5 text-left text-[13px] leading-relaxed text-neutral-600 sm:text-sm">${bullets}</ul><p class="mx-auto max-w-2xl text-center text-xs text-neutral-500">${P.showing}</p></section><section aria-label="Lease cards" class="mx-auto w-full max-w-7xl px-4 sm:px-6"><div class="grid grid-cols-1 gap-5 sm:grid-cols-2 sm:gap-6 lg:grid-cols-3">${cards}</div><p class="mx-auto mt-8 max-w-3xl text-center text-xs text-neutral-500">${P.baseNote} <em>${P.baseNoteEm}</em></p></section><section id="comparison" aria-labelledby="comparison-heading" class="mx-auto w-full max-w-7xl space-y-6 px-4 sm:px-6 scroll-mt-24"><div class="mx-auto max-w-3xl space-y-3 text-center"><div class="inline-flex items-center gap-2 rounded-full border border-neutral-200 bg-white px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.25em] text-neutral-500 shadow-xs">${P.compare.badge}</div><h2 id="comparison-heading" class="font-serif text-3xl font-medium tracking-tight text-neutral-950 sm:text-4xl md:text-5xl">${P.compare.title}</h2><p class="text-sm leading-relaxed text-neutral-600 sm:text-base">${P.compare.intro}</p></div><p class="font-mono text-[10px] uppercase tracking-wider text-neutral-500 sm:hidden">${P.compare.swipe}</p><div class="overflow-x-auto rounded-2xl border border-neutral-200 bg-white shadow-xs"><table class="w-full min-w-[1800px] text-left text-xs" id="comparison-table"><thead class="bg-[#F6F5F2] font-mono text-[10px] uppercase text-neutral-600"><tr>${ths}</tr></thead><tbody class="divide-y divide-neutral-100 text-neutral-800">${rows}</tbody></table></div></section></div>`;
  page({ file: 'lease-pipeline.html', active: 'lease-pipeline', title: `Lease Pipeline — ${B.name}`, description: P.intro, body, jsonLd });
}

